function.arguments:
{"script":"() => {
  const partners = Array.from(document.querySelectorAll('a[href*="/partners/"]')).map(a => {
    const nameEl = a.querySelector('p:first-of-type');
    const countryEl = a.querySelector('p:nth-of-type(2)');
    return {
      name: nameEl ? nameEl.textContent.trim() : null,
      country: countryEl ? countryEl.textContent.trim() : null,
      href: a.href
    };
  });
  const filteredPartners = partners.filter(p => p.country && p.country.includes('澳大利亚') || p.country && p.country.includes('Australia'));
  return {
    totalPartnersOnPage: partners.length,
    australianPartners: filteredPartners,
    allPartnerNames: partners.map(p => p.name)
  };
}"}

