function.arguments:
{"script":"() => {
  const allPartnerLinks = document.querySelectorAll('a[href*="/partners/"]');
  const partners = [];
  allPartnerLinks.forEach(a => {
    const text = a.textContent.trim();
    const ps = a.querySelectorAll('p');
    if (ps.length >= 2) {
      partners.push({
        name: ps[0].textContent.trim(),
        country: ps[1].textContent.trim(),
        href: a.href
      });
    }
  });
  return { count: partners.length, partners: partners };
}"}

