function.arguments:
{"script":"() => {
  // Find all links to /partners/ and extract names and countries
  const links = document.querySelectorAll('a');
  const results = [];
  links.forEach(a => {
    const ps = a.querySelectorAll('p');
    if (ps.length >= 2) {
      const name = ps[0].textContent.trim();
      const country = ps[1].textContent.trim();
      results.push({ name, country });
    }
  });
  // Filter for Australia
  const aus = results.filter(r => r.country === '澳大利亚');
  return { total: results.length, australian: aus };
}"}

